function detectParse(rows) {
  for (let i = 0; i < Math.min(rows.length, 10); i++) {
    for (const [k, cfg] of Object.entries(OTA)) {
      if (cfg.det(rows[i])) {
        const hd = rows[i],
          data = [];
        let totalValid = 0,
          skippedOther = 0;
        const skipSPK = !!cfg.skipSPKFilter;
        for (let j = i + 1; j < rows.length; j++) {
          if (rows[j].length < 3 || !rows[j][0]) continue;
          try {
            const p = cfg.parse(rows[j], hd);
            if (p && p.lendDate && p.status !== "cancelled") {
              totalValid++;
              if (!skipSPK) {
                const rowText = rows[j].join(",").toUpperCase();
                if (!rowText.includes("札幌")) {
                  skippedOther++;
                  continue;
                }
              }
              if (["B2", "A2", "D"].includes(p.vehicle)) {
                skippedOther++;
                continue;
              }
              p.delTime = p.delTime || p.lendTime;
              p.colTime = p.colTime || p.returnTime;
              p.delPlace = p.delPlace || "";
              p.colPlace = p.colPlace || "";
              if (!p.id) {
                p.id = "NOID_" + k + "_" + Date.now() + "_" + j;
                console.warn("[CSV] 予約番号なし→自動ID:", p.id, p.name);
              }
              data.push(p);
            }
          } catch (e) {}
        }
        return {
          ota: k,
          data,
          totalValid,
          skippedOther
        };
      }
    }
  }
  return null;
}
function buildRepeaterMap(reservations) {
  const telMap = {};
  const mailMap = {};
  reservations.forEach(r => {
    const tel = (r.tel || "").replace(/[-\s\(\)]/g, "").trim();
    const mail = (r.mail || "").trim().toLowerCase();
    if (tel && tel.length >= 5) {
      if (!telMap[tel]) telMap[tel] = [];
      telMap[tel].push(r);
    }
    if (mail && mail.includes("@")) {
      if (!mailMap[mail]) mailMap[mail] = [];
      mailMap[mail].push(r);
    }
  });
  const parent = {};
  const find = x => {
    if (!parent[x]) parent[x] = x;
    return parent[x] === x ? x : parent[x] = find(parent[x]);
  };
  const union = (a, b) => {
    const pa = find(a),
      pb = find(b);
    if (pa !== pb) parent[pb] = pa;
  };
  reservations.forEach(r => {
    const tel = (r.tel || "").replace(/[-\s\(\)]/g, "").trim();
    const mail = (r.mail || "").trim().toLowerCase();
    if (tel && tel.length >= 5 && telMap[tel]) {
      telMap[tel].forEach(r2 => {
        if (r2.id !== r.id) union(r.id, r2.id);
      });
    }
    if (mail && mail.includes("@") && mailMap[mail]) {
      mailMap[mail].forEach(r2 => {
        if (r2.id !== r.id) union(r.id, r2.id);
      });
    }
  });
  const groups = {};
  reservations.forEach(r => {
    const g = find(r.id);
    if (!groups[g]) groups[g] = [];
    groups[g].push(r);
  });
  const repeaterGroups = {};
  Object.entries(groups).forEach(([gid, members]) => {
    if (members.length >= 2) repeaterGroups[gid] = members;
  });
  const isRepeater = {};
  const repeaterGroupOf = {};
  Object.entries(repeaterGroups).forEach(([gid, members]) => {
    members.forEach(r => {
      isRepeater[r.id] = true;
      repeaterGroupOf[r.id] = gid;
    });
  });
  return {
    repeaterGroups,
    isRepeater,
    repeaterGroupOf,
    groups
  };
}
