const KPI_PERIOD_START = {
  spk: "2026-02",
  nha: "2026-04",
  bt: "2026-05"
};
function computeVehicleRanking(vehicles, data, fleet, kpiAll, st, otaFilter, maintenance) {
  const PERIOD_START = KPI_PERIOD_START[st] || "2026-02";
  otaFilter = otaFilter || "ALL";
  if (!vehicles || !vehicles.length) return {
    rows: [],
    classRows: [],
    period: "",
    months: 0,
    empty: false
  };
  const today = new Date();
  const todayYM = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, "0")}`;
  let effectiveStart = PERIOD_START;
  if (st === "bt") {
    const firstYms = (data || []).filter(r => r.status !== "cancelled" && r.lendDate).map(r => r.lendDate.slice(0, 7)).sort();
    if (firstYms.length === 0) return {
      rows: [],
      classRows: [],
      period: "予約待ち",
      months: 0,
      empty: true
    };
    effectiveStart = firstYms[0];
  }
  const monthList = [];
  let [cy, cm] = effectiveStart.split("-").map(Number);
  const ey = today.getFullYear(),
    em = today.getMonth() + 1;
  while (cy < ey || cy === ey && cm <= em) {
    monthList.push(`${cy}-${String(cm).padStart(2, "0")}`);
    cm++;
    if (cm > 12) {
      cm = 1;
      cy++;
    }
  }
  const n_months = monthList.length;
  if (n_months <= 0) return {
    rows: [],
    classRows: [],
    period: "",
    months: 0,
    empty: false
  };
  const todayStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, "0")}-${String(today.getDate()).padStart(2, "0")}`;
  const activeResv = (data || []).filter(r => {
    if (r.status === "cancelled") return false;
    if (!r.lendDate) return false;
    if (r.lendDate < effectiveStart + "-01") return false;
    if (otaFilter !== "ALL") {
      const ota = r.ota === "A" ? "O" : r.ota || "?";
      if (ota !== otaFilter) return false;
    }
    return true;
  });
  const resvMap = {};
  activeResv.forEach(r => {
    resvMap[r.id] = r;
  });
  const vehStat = {};
  Object.entries(fleet || {}).forEach(([rid, vc]) => {
    const r = resvMap[rid];
    if (!r) return;
    const ld = r.lendDate,
      rd = r.returnDate;
    if (!ld || !rd) return;
    let d2 = new Date(rd);
    if (d2 > today) d2 = today;
    const d1 = new Date(ld);
    const days = Math.max(1, Math.floor((d2 - d1) / 86400000) + 1);
    if (!vehStat[vc]) vehStat[vc] = {
      cnt: 0,
      rev: 0,
      days: 0
    };
    vehStat[vc].cnt += 1;
    {
      const bp = Number(r.basePrice) || 0,
        op = Number(r.optionPrice) || 0,
        dc = Number(r.discount) || 0;
      vehStat[vc].rev += bp > 0 || op > 0 ? bp + op - dc : Number(r.price) || 0;
    }
    vehStat[vc].days += days;
  });
  const kpiByMonth = {};
  (kpiAll || []).forEach(k => {
    if (!kpiByMonth[k.year_month]) kpiByMonth[k.year_month] = {};
    kpiByMonth[k.year_month][k.vehicle_code] = k.active;
  });
  const maintDaysByVeh = {};
  (maintenance || []).forEach(mm => {
    const bt = mm.blockType || mm.block_type;
    if (bt && bt !== "maintenance") return;
    const sD = mm.startDate || mm.start_date,
      eD = mm.endDate || mm.end_date;
    if (!sD || !eD) return;
    const vc = mm.vehicleCode || mm.vehicle_code;
    if (!vc) return;
    const set = maintDaysByVeh[vc] || (maintDaysByVeh[vc] = new Set());
    for (let d = new Date(sD.slice(0, 10) + "T00:00:00"), e = new Date(eD.slice(0, 10) + "T00:00:00"); d <= e; d.setDate(d.getDate() + 1)) set.add(d.toISOString().slice(0, 10));
  });
  const capByVeh = {},
    usedByVeh = {};
  monthList.forEach(ym => {
    const [yy, mm] = ym.split("-").map(Number);
    const dim = new Date(yy, mm, 0).getDate();
    const ms = new Date(yy, mm - 1, 1),
      me = new Date(yy, mm - 1, dim);
    const monthKpi = kpiByMonth[ym] || {};
    (vehicles || []).forEach(v => {
      if (!v.active) return;
      const isActive = v.code in monthKpi ? monthKpi[v.code] : true;
      if (!isActive) return;
      const allM = maintDaysByVeh[v.code] || null;
      const mSet = new Set();
      if (allM) allM.forEach(dd => {
        const dt = new Date(dd + "T00:00:00");
        if (dt >= ms && dt <= me) mSet.add(dd);
      });
      const availV = dim - mSet.size;
      if (availV <= 0) return;
      capByVeh[v.code] = (capByVeh[v.code] || 0) + availV;
      const days = new Set();
      activeResv.forEach(r => {
        if ((fleet || {})[r.id] !== v.code) return;
        const ld = r.lendDate,
          rd = r.returnDate;
        if (!ld || !rd) return;
        const lDate = new Date(ld.slice(0, 10) + "T00:00:00"),
          rDate = new Date(rd.slice(0, 10) + "T00:00:00");
        const s = lDate > ms ? lDate : ms,
          e = rDate < me ? rDate : me;
        for (let d = new Date(s); d <= e; d.setDate(d.getDate() + 1)) days.add(d.toISOString().slice(0, 10));
      });
      mSet.forEach(dd => days.delete(dd));
      usedByVeh[v.code] = (usedByVeh[v.code] || 0) + days.size;
    });
  });
  const rows = (vehicles || []).filter(v => v.active).map(v => {
    const s = vehStat[v.code] || {
      cnt: 0,
      rev: 0,
      days: 0
    };
    const lease = Number(v.leaseMonthly || v.lease_monthly) || 0;
    const ins = Number(v.insuranceAnnual || v.insurance_annual) || 0;
    const shaken = (Number(v.shakenCost || v.shaken_cost) || 0) / 24;
    const tenken = (Number(v.tenkenCost || v.tenken_cost) || 0) / 6;
    const fixedMonthly = lease + ins + shaken + tenken;
    const revTotal = s.rev;
    const monthlyAvg = revTotal / n_months;
    const capDays = capByVeh[v.code] || 0;
    const usedDaysReal = usedByVeh[v.code] || 0;
    const utilPct = capDays ? usedDaysReal / capDays * 100 : 0;
    const fixedTotal = fixedMonthly * n_months;
    const profit = revTotal - fixedTotal;
    const monthlyProfit = profit / n_months;
    const isActiveNow = (() => {
      const monthKpi = kpiByMonth[todayYM] || {};
      return v.code in monthKpi ? monthKpi[v.code] : true;
    })();
    return {
      ...v,
      plate: v.no || v.plate_no || "",
      cnt: s.cnt,
      usedDays: usedDaysReal,
      capDays,
      revTotal,
      monthlyAvg,
      utilPct,
      fixedMonthly,
      fixedTotal,
      profit,
      monthlyProfit,
      isActiveNow,
      fixedBreak: {
        lease,
        ins,
        shaken,
        tenken
      }
    };
  });
  const maxRev = Math.max(1, ...rows.filter(r => r.revTotal > 0).map(r => r.revTotal));
  const maxAvg = Math.max(1, ...rows.filter(r => r.monthlyAvg > 0).map(r => r.monthlyAvg));
  const maxUtil = Math.max(1, ...rows.filter(r => r.utilPct > 0).map(r => r.utilPct));
  const maxProfit = Math.max(1, ...rows.filter(r => r.profit > 0).map(r => r.profit));
  const calc = (v, mx, w) => {
    if (v <= 0 || mx <= 0) return 0;
    return Math.min(w, v / mx * w);
  };
  rows.forEach(r => {
    r.sRev = Math.round(calc(r.revTotal, maxRev, 25) * 10) / 10;
    r.sAvg = Math.round(calc(r.monthlyAvg, maxAvg, 15) * 10) / 10;
    r.sUtil = Math.round(calc(r.utilPct, maxUtil, 25) * 10) / 10;
    r.sProfit = Math.round(calc(r.profit, maxProfit, 35) * 10) / 10;
    r.totalScore = Math.round((r.sRev + r.sAvg + r.sUtil + r.sProfit) * 10) / 10;
    const t = r.totalScore;
    r.rank = t >= 80 ? "S" : t >= 60 ? "A" : t >= 40 ? "B" : t >= 20 ? "C" : "D";
  });
  rows.sort((a, b) => b.totalScore - a.totalScore);
  const byClass = {};
  rows.forEach(r => {
    const c = r.type || "?";
    if (!byClass[c]) byClass[c] = {
      class: c,
      vehicles: [],
      totalRev: 0,
      totalProfit: 0,
      totalFixed: 0,
      totalDays: 0,
      totalCapDays: 0,
      count: 0
    };
    byClass[c].vehicles.push(r);
    byClass[c].totalRev += r.revTotal;
    byClass[c].totalProfit += r.profit;
    byClass[c].totalFixed += r.fixedTotal;
    byClass[c].totalDays += r.usedDays;
    byClass[c].totalCapDays += r.capDays;
    byClass[c].count += 1;
  });
  const classRows = Object.values(byClass).map(c => ({
    ...c,
    monthlyAvg: c.totalRev / n_months,
    utilPct: c.totalCapDays ? c.totalDays / c.totalCapDays * 100 : 0,
    monthlyProfit: c.totalProfit / n_months,
    best: c.vehicles[0]
  })).sort((a, b) => b.totalProfit - a.totalProfit);
  return {
    rows,
    classRows,
    period: `${effectiveStart} 〜 ${todayYM}`,
    months: n_months,
    empty: false
  };
}
